async function yukla(url) {
  try {
    const javob = await fetch(url);
    if (!javob.ok) throw new Error(`HTTP ${javob.status}`);
    return await javob.json();
  } catch (xato) {
    console.error('Yuklash xatosi:', xato);
    throw xato;
  }
}

